const event = $json.body ?? $json;
if (event.action !== 'opened' || !event.issue || event.issue.pull_request) {
  return [];
}
const text = [event.issue.title, event.issue.body || ''].join(' ').toLowerCase();
const labels = ['needs-triage'];
if (/\b(bug|error|exception|crash|regression|fail(?:ure|ing)?)\b/.test(text)) labels.push('bug');
else if (/\b(doc|readme|guide|tutorial|documentation)\b/.test(text)) labels.push('documentation');
else if (/\b(feature|request|support|add)\b/.test(text)) labels.push('feature');
else if (/\b(question|how do|help)\b/.test(text)) labels.push('question');
if (/\b(security|safety|data loss|outage|critical)\b/.test(text)) labels.push('priority:high');
else if (/\b(performance|reliability|deployment|ci)\b/.test(text)) labels.push('priority:medium');
else labels.push('priority:low');
return [{ json: { issue_number: event.issue.number, labels: [...new Set(labels)] } }];
